async function loadDashboard() {
  const [user, posts, alerts] = await Promise.all([
    fetch('/api/user').then((res) => res.json()),
    fetch('/api/posts').then((res) => res.json()),
    fetch('/api/alerts').then((res) => res.json()),
  ]);

  return { user, posts, alerts };
}
```

